protected readonly moorTotal = computed(() =>
  trimmedTotal((this.people() ?? []).map((p) => ({ value: p.moor, hold: p.hold }))),
);

// The highest moor among the people not on hold, skipping n/a; n/a when there is none.
protected readonly moorTop = computed(() => {
  const values = (this.people() ?? [])
    .filter((p) => !p.hold)
    .map((p) => p.moor)
    .filter((v): v is number => v !== null);
  return values.length === 0 ? null : Math.max(...values);
});

// The highest moor minus the lowest among the people not on hold (n/a moors skipped); null (n/a) when nobody has one.
protected readonly moorSpread = computed(() => {
  const values = (this.people() ?? [])
    .filter((p) => !p.hold)
    .map((p) => p.moor)
    .filter((v): v is number => v !== null);
  return values.length === 0 ? null : Math.max(...values) - Math.min(...values);
});

// The highest rigging among the people not on hold, skipping n/a; n/a when there is none.
protected readonly riggingTop = computed(() => {
  const values = (this.people() ?? [])
    .filter((p) => !p.hold)
  () => countable(this.people() ?? []).filter((p) => p.mast !== null && p.mast % 2 === 0).length,
);

// How many counted people have an even rigging (n/a riggings are not counted).
protected readonly riggingEven = computed(
  () =>
    countable(this.people() ?? []).filter((p) => p.rigging !== null && p.rigging % 2 === 0).length,
);

// How many counted people have an even moor (n/a moors are not counted).
protected readonly moorEven = computed(
  () => countable(this.people() ?? []).filter((p) => p.moor !== null && p.moor % 2 === 0).length,
);

// The average rigging among the people not on hold (n/a riggings skipped), rounded like every
// divide; null (n/a) when nobody has one.
protected readonly riggingMean = computed(() => {
  const values = (this.people() ?? [])
